CREATE TABLE public.job_email_attempts (operation_key text PRIMARY KEY, event_id uuid NOT NULL REFERENCES public.events(id), technician_id uuid NOT NULL REFERENCES public.technicians(id), outcome text NOT NULL DEFAULT 'pending' CHECK(outcome IN ('pending','accepted','failed')), graph_status integer, reason_code text, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
GRANT ALL ON public.job_email_attempts TO service_role;
ALTER TABLE public.job_email_attempts ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.claim_job_email_attempt(_key text,_event uuid,_technician uuid,_retry boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE claimed text; BEGIN IF length(_key)>512 OR NOT EXISTS(SELECT 1 FROM public.events e JOIN public.event_technicians a ON a.event_id=e.id WHERE e.id=_event AND e.deleted_at IS NULL AND a.technician_id=_technician) THEN RAISE EXCEPTION 'invalid live assignment'; END IF; INSERT INTO public.job_email_attempts(operation_key,event_id,technician_id) VALUES(_key,_event,_technician) ON CONFLICT DO NOTHING RETURNING operation_key INTO claimed; IF claimed IS NOT NULL THEN RETURN true; END IF; IF _retry THEN UPDATE public.job_email_attempts SET outcome='pending',finished_at=NULL WHERE operation_key=_key AND event_id=_event AND technician_id=_technician AND outcome='failed' RETURNING operation_key INTO claimed; END IF; RETURN claimed IS NOT NULL; END; $$;
REVOKE ALL ON FUNCTION public.claim_job_email_attempt(text,uuid,uuid,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_job_email_attempt(text,uuid,uuid,boolean) TO service_role;